{
  "name": "TCP/IP网络连接适配器",
  "name_en": "TCP/IP Connection Adapter",
  "manufacturer": "",
  "description": "非物理软件组件，用于实验控制软件通过套接字与仪器或网络服务建立TCP/IP通信。它负责打开和关闭连接、监听传入数据、发送与接收消息，以及检查连接是否仍然可用。",
  "description_en": "A non-physical software component that enables laboratory control software to communicate with instruments or network services over a TCP/IP socket. It handles opening and closing the connection, listening for incoming data, transmitting and receiving messages, and checking whether the connection is still available.",
  "actions": [
    {
      "action_name": "auto-open_connection",
      "description": "打开TCP/IP套接字连接。",
      "description_en": "Open the TCP/IP socket connection."
    },
    {
      "action_name": "auto-connection_listener",
      "description": "监听连接中的新数据并将其写入接收缓冲区。",
      "description_en": "Listen for new data on the connection and place it into the receive buffer."
    },
    {
      "action_name": "auto-close_connection",
      "description": "关闭TCP/IP连接。",
      "description_en": "Close the TCP/IP connection."
    },
    {
      "action_name": "auto-is_connection_open",
      "description": "检查TCP/IP套接字连接是否处于打开状态。",
      "description_en": "Check whether the TCP/IP socket connection is open."
    },
    {
      "action_name": "auto-transmit",
      "description": "通过TCP/IP套接字发送消息。",
      "description_en": "Send a message through the TCP/IP socket."
    },
    {
      "action_name": "auto-receive",
      "description": "从接收缓冲区读取通过TCP/IP连接收到的数据。",
      "description_en": "Read data received through the TCP/IP connection from the receive buffer."
    }
  ],
  "tag_hints": [
    "TCP/IP socket communication",
    "instrument networking",
    "message transmit/receive",
    "connection status check",
    "asynchronous receive listener",
    "lab software connectivity"
  ]
}

